CREATE DATABASE IF NOT EXISTS lostlink_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lostlink_db;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reports (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, report_type ENUM('lost','found') NOT NULL, item_name VARCHAR(150) NOT NULL, color VARCHAR(50), location VARCHAR(150) NOT NULL, event_date DATE NOT NULL, description TEXT, photo_path VARCHAR(255), status ENUM('open','resolved') NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_report_search(report_type,status,category_id,event_date), INDEX idx_report_location(location)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS matches (id INT AUTO_INCREMENT PRIMARY KEY, lost_report_id INT NOT NULL, found_report_id INT NOT NULL, score DECIMAL(5,2) NOT NULL, contributions JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_report_pair(lost_report_id,found_report_id), FOREIGN KEY(lost_report_id) REFERENCES reports(id), FOREIGN KEY(found_report_id) REFERENCES reports(id), CHECK(score BETWEEN 0 AND 100), CHECK(lost_report_id <> found_report_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS claims (id INT AUTO_INCREMENT PRIMARY KEY, match_id INT NOT NULL, claimant_name VARCHAR(150) NOT NULL, contact VARCHAR(100), proof_description TEXT NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME, FOREIGN KEY(match_id) REFERENCES matches(id), INDEX idx_claim_status(status)) ENGINE=InnoDB;
